@props([ 'id' => null, 'search' => true, 'searchPlaceholder' => 'Cari data...', 'searchName' => 'q', 'endpoint' => null, 'refreshable' => false, 'autoRefresh' => null, 'autoRefreshToggle' => false, ]) @php $tableId = $id ?: 'ui-datatable-' . uniqid(); $autoRefreshInterval = is_numeric($autoRefresh) ? (int)$autoRefresh : ($autoRefresh ? 10000 : null); @endphp <div id="{{ $tableId }}" {{ $attributes-> merge(['class' => 'ui-datatable-wrapper']) }} data-ui-datatable="{{ $tableId }}" @if($endpoint) data-ui-refresh-url="{{ $endpoint }}" @endif @if($autoRefreshInterval) data-ui-auto-refresh="{{ $autoRefreshInterval }}" @endif > @if($search || isset($actions) || $refreshable || $autoRefreshToggle) <div class="ui-datatable-toolbar"><div style="flex: 1; max-width: 320px;"> @if($search) <x-ui.search :placeholder="$searchPlaceholder" :name="$searchName" /> @endif </div><div style="display: flex; align-items: center; gap: 10px; flex-wrap: wrap;"> @if(isset($actions) ) {{ $actions }} @endif @if($autoRefreshToggle) <div style="display: inline-flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text-muted); background: rgba(255,255,255,0.04); padding: 4px 10px; border-radius: var(--ui-radius-sm); border: 1px solid var(--border-color);"><label class="ui-check-label" style="font-size: 12px; margin: 0; cursor: pointer;"><input type="checkbox" class="ui-checkbox" data-ui-table-auto-refresh="{{ $tableId }}" data-interval="{{ $autoRefreshInterval ?: 10000 }}" @if($autoRefreshInterval) checked @endif ><span> Auto Refresh </span></label></div> @endif @if($refreshable) <x-ui.button type="button" size="sm" variant="secondary" icon="fa-solid fa-rotate" data-ui-table-refresh="{{ $tableId }}" title="Segarkan data tabel" > Refresh </x-ui.button> @endif </div></div> @endif <div class="ui-datatable-content">{{ $slot }}</div> @if(isset($pagination) ) <div class="ui-datatable-pagination">{{ $pagination }}</div> @endif </div>